package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	reader := bufio.NewReader(os.Stdin)
	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()

	var n int
	fmt.Fscan(reader, &n)
	var s string
	fmt.Fscan(reader, &s)

	count := 0
	res := 0
	for i := 0; i < len(s); i++ {
		if s[i] == 'x' {
			count++
			if count >= 3 {
				res++
				count--
			}
		} else {
			count = 0
		}
	}
	fmt.Fprintln(writer, res)
}
